internal object HarnessRuntimeHarnessListSessionCheckpointsOperation {
    /**
     * Keyset-paginated on an opaque cursor, like ListSessions.
     *
     * @param sessionId The session UUID.
     * @param pageSize Page size. Defaults to 50 when omitted or non-positive.
     * @param pageToken Opaque keyset cursor returned by the previous page. Empty
     *   starts from the beginning.
     */
    fun harnessListSessionCheckpoints(clientConfig: ClientConfig, sessionId: String, pageSize: Int? = null, pageToken: String? = null, options: RequestOptions? = null): ListCheckpointsResponse {
        return SdkClient.request<ListCheckpointsResponse>(SdkClient.RequestSpec("GET", "/v2/agents/sessions/${SdkClient.encodePathSegment(sessionId)}/checkpoints", config = clientConfig, query = mapOf("page_size" to SdkClient.queryValue(pageSize, "form", true), "page_token" to
    SdkClient.queryValue(pageToken, "form", true)), operationId = "harnessListSessionCheckpoints", decoder = SdkClient.ResponseDecoder.JSON, options = options, errors = mapOf("400" to Error2::class.java, "401" to Error2::class.java, "403" to Error2::class.java, "404" to Error2::class.java, "423" to Error2::class.java, "429" to Error2::class.java, "500" to Error2::class.java, "default" to Error2::class.java))).data
    }






    /**
     * Keyset-paginated on an opaque cursor, like ListSessions.
     *
     * @param sessionId The session UUID.
     * @param pageSize Page size. Defaults to 50 when omitted or non-positive.
     * @param pageToken Opaque keyset cursor returned by the previous page. Empty
     *   starts from the beginning.
     */
    fun harnessListSessionCheckpointsPaginated(clientConfig: ClientConfig, sessionId: String, pageSize: Int? = null, pageToken: String? = null, options: RequestOptions? = null, yieldFn: (Checkpoint) -> Boolean) {
        var cursor = pageToken
        while (true) {
            val page = harnessListSessionCheckpoints(clientConfig, sessionId, pageSize, cursor, options)
            val items = page.checkpoints.orEmpty()
            if (items.isEmpty()) return
            for (item in items) {
                if (!yieldFn(item)) return
            }
            val nextCursor = page.nextPageToken ?: return
            cursor = nextCursor
        }
    }



    fun harnessListSessionCheckpointsPages(clientConfig: ClientConfig, sessionId: String, pageSize: Int? = null, pageToken: String? = null, options: RequestOptions? = null, yieldPage: (HarnessRuntime.HarnessListSessionCheckpointsPage) -> Boolean) {
        var cursor = pageToken
        while (true) {
            val page = harnessListSessionCheckpoints(clientConfig, sessionId, pageSize, cursor, options)
            val items = page.checkpoints.orEmpty()
            if (items.isEmpty()) return
            val nextCursor = page.nextPageToken
            val hasMore = nextCursor != null
            if (!yieldPage(HarnessRuntime.HarnessListSessionCheckpointsPage(page, items, hasMore))) return
            if (!hasMore) return
            cursor = nextCursor
        }
    }
}

